window.YKI_LISTEN = [{"id": "l1", "theme": 2, "kind": "Berättelse", "title_sv": "Saras vanliga dag", "title_en": "Sara's normal day", "src": "audio/l1.mp3", "src_sv": "audio/l1-sv.mp3", "dur": 210.8, "dur_sv": 76.7, "lines": [{"p": "A", "sv": "Hej! Jag heter Sara.", "en": "Hi! My name is Sara.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Jag är trettiofem år och bor i Vanda.", "en": "I am thirty-five and live in Vantaa.", "t": 9.15, "t2": 3.89}, {"p": "A", "sv": "Jag bor i en tvåa med min man och vår son.", "en": "I live in a two-room flat with my husband and our son.", "t": 20.04, "t2": 7.82}, {"p": "A", "sv": "Jag vaknar klockan sex varje morgon.", "en": "I wake up at six every morning.", "t": 31.72, "t2": 11.74}, {"p": "A", "sv": "Först dricker jag kaffe och äter frukost.", "en": "First I drink coffee and have breakfast.", "t": 42.81, "t2": 15.96}, {"p": "A", "sv": "Sedan tar jag bussen till jobbet.", "en": "Then I take the bus to work.", "t": 54.04, "t2": 19.95}, {"p": "A", "sv": "Bussen går klockan sju och tio.", "en": "The bus leaves at ten past seven.", "t": 63.15, "t2": 23.36}, {"p": "A", "sv": "Jag jobbar på ett daghem.", "en": "I work at a day-care centre.", "t": 73.36, "t2": 27.05}, {"p": "A", "sv": "Jag tycker om mitt jobb, för barnen är glada och roliga.", "en": "I like my job, because the children are happy and funny.", "t": 81.31, "t2": 29.76}, {"p": "A", "sv": "Men ibland är jobbet tungt, och jag blir trött.", "en": "But sometimes the work is heavy, and I get tired.", "t": 94.27, "t2": 34.3}, {"p": "A", "sv": "Jag slutar klockan tre.", "en": "I finish at three.", "t": 106.63, "t2": 38.66}, {"p": "A", "sv": "Efter jobbet handlar jag mat i affären nära vårt hus.", "en": "After work I buy food in the shop near our house.", "t": 114.51, "t2": 41.58}, {"p": "A", "sv": "Jag köper mjölk, bröd, grönsaker och fisk.", "en": "I buy milk, bread, vegetables and fish.", "t": 128.59, "t2": 46.76}, {"p": "A", "sv": "Hemma lagar jag middag, och vi äter tillsammans klockan fem.", "en": "At home I cook dinner, and we eat together at five.", "t": 142.48, "t2": 51.83}, {"p": "A", "sv": "På kvällen hjälper jag min son med läxorna.", "en": "In the evening I help my son with his homework.", "t": 156.14, "t2": 56.81}, {"p": "A", "sv": "Två gånger i veckan går jag på en kurs i svenska.", "en": "Twice a week I go to a Swedish course.", "t": 167.14, "t2": 60.65}, {"p": "A", "sv": "Svenska är svårt, men det är också roligt.", "en": "Swedish is difficult, but it is also fun.", "t": 179.19, "t2": 65.18}, {"p": "A", "sv": "Klockan tio går jag och lägger mig.", "en": "At ten o'clock I go to bed.", "t": 192.29, "t2": 69.95}, {"p": "A", "sv": "I morgon är en ny dag!", "en": "Tomorrow is a new day!", "t": 201.93, "t2": 73.44}], "q": [{"sv": "Var jobbar Sara?", "en": "Where does Sara work?", "o": ["På ett sjukhus", "På ett daghem", "I en affär"], "a": 1}, {"sv": "Hur åker Sara till jobbet?", "en": "How does Sara get to work?", "o": ["Med bil", "Med cykel", "Med buss"], "a": 2}, {"sv": "Vad gör Sara två gånger i veckan?", "en": "What does Sara do twice a week?", "o": ["Hon går på en svenskkurs", "Hon simmar", "Hon städar"], "a": 0}]}, {"id": "l2", "theme": 1, "kind": "Dialog", "title_sv": "Nya grannar", "title_en": "New neighbours", "src": "audio/l2.mp3", "src_sv": "audio/l2-sv.mp3", "dur": 163.9, "dur_sv": 61.3, "lines": [{"p": "A", "sv": "Hej! Jag tror inte att vi har träffats. Jag heter Mikael.", "en": "Hi! I don't think we have met. My name is Mikael.", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Hej Mikael! Jag heter Omar. Jag flyttade in förra veckan.", "en": "Hi Mikael! My name is Omar. I moved in last week.", "t": 14.35, "t2": 5.94}, {"p": "A", "sv": "Välkommen till huset! Var bor du?", "en": "Welcome to the building! Where do you live?", "t": 29.47, "t2": 11.58}, {"p": "B", "sv": "Jag bor på tredje våningen, i lägenhet tolv.", "en": "I live on the third floor, in flat twelve.", "t": 40.03, "t2": 15.41}, {"p": "A", "sv": "Vad roligt! Jag bor på andra våningen. Bor du ensam?", "en": "How nice! I live on the second floor. Do you live alone?", "t": 52.17, "t2": 19.9}, {"p": "B", "sv": "Nej, jag bor med min fru och våra två döttrar.", "en": "No, I live with my wife and our two daughters.", "t": 66.54, "t2": 25.16}, {"p": "A", "sv": "Hur gamla är de?", "en": "How old are they?", "t": 78.58, "t2": 29.49}, {"p": "B", "sv": "De är fem och åtta år.", "en": "They are five and eight.", "t": 84.91, "t2": 31.82}, {"p": "A", "sv": "Mina barn är också små. De kan leka tillsammans på gården.", "en": "My children are also small. They can play together in the yard.", "t": 93.17, "t2": 34.9}, {"p": "B", "sv": "Ja, gärna! Förresten, var är tvättstugan?", "en": "Yes, please! By the way, where is the laundry room?", "t": 108.17, "t2": 40.36}, {"p": "A", "sv": "Den är i källaren. Man bokar en tid på listan vid dörren.", "en": "It's in the basement. You book a time on the list by the door.", "t": 121.2, "t2": 45.07}, {"p": "B", "sv": "Tack för hjälpen!", "en": "Thanks for the help!", "t": 136.15, "t2": 50.71}, {"p": "A", "sv": "Ingen orsak. Trevligt att träffas!", "en": "You're welcome. Nice to meet you!", "t": 142.82, "t2": 53.19}, {"p": "B", "sv": "Detsamma! Ha en bra dag!", "en": "Likewise! Have a nice day!", "t": 153.63, "t2": 57.4}], "q": [{"sv": "När flyttade Omar in?", "en": "When did Omar move in?", "o": ["I går", "Förra veckan", "Förra året"], "a": 1}, {"sv": "Hur många barn har Omar?", "en": "How many children does Omar have?", "o": ["Ett", "Två", "Tre"], "a": 1}, {"sv": "Var är tvättstugan?", "en": "Where is the laundry room?", "o": ["I källaren", "På gården", "På tredje våningen"], "a": 0}]}, {"id": "l3", "theme": 1, "kind": "Telefonsamtal", "title_sv": "Kommer du på min fest?", "title_en": "Are you coming to my party?", "src": "audio/l3.mp3", "src_sv": "audio/l3-sv.mp3", "dur": 159.4, "dur_sv": 59.4, "lines": [{"p": "A", "sv": "Hej, det är Lisa!", "en": "Hi, it's Lisa!", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Hej Lisa! Hur mår du?", "en": "Hi Lisa! How are you?", "t": 8.39, "t2": 3.46}, {"p": "A", "sv": "Bra, tack! Jag ringer för att jag fyller fyrtio år på lördag.", "en": "Fine, thanks! I'm calling because I turn forty on Saturday.", "t": 17.55, "t2": 6.87}, {"p": "B", "sv": "Oj, grattis i förväg!", "en": "Oh, happy birthday in advance!", "t": 31.82, "t2": 11.96}, {"p": "A", "sv": "Tack! Jag har en fest hemma hos mig. Kan du komma?", "en": "Thanks! I'm having a party at my place. Can you come?", "t": 41.22, "t2": 15.13}, {"p": "B", "sv": "Vilken tid börjar festen?", "en": "What time does the party start?", "t": 53.69, "t2": 19.65}, {"p": "A", "sv": "Klockan sex på kvällen.", "en": "At six in the evening.", "t": 62.45, "t2": 22.82}, {"p": "B", "sv": "Tyvärr jobbar jag till klockan sju. Men jag kan komma lite senare.", "en": "Unfortunately I work until seven. But I can come a bit later.", "t": 70.6, "t2": 25.81}, {"p": "A", "sv": "Det är inga problem. Kom när du kan!", "en": "That's no problem. Come when you can!", "t": 85.67, "t2": 31.29}, {"p": "B", "sv": "Ska jag ta med något?", "en": "Should I bring something?", "t": 95.84, "t2": 35.04}, {"p": "A", "sv": "Nej tack, du behöver inte ta med något. Jag lagar mycket mat.", "en": "No thanks, you don't need to bring anything. I'm cooking a lot of food.", "t": 102.37, "t2": 37.3}, {"p": "B", "sv": "Okej. Vad är din adress?", "en": "OK. What is your address?", "t": 118.53, "t2": 43.38}, {"p": "A", "sv": "Björkvägen fem. Jag skickar adressen i ett meddelande.", "en": "Björkvägen five. I'll send the address in a message.", "t": 128.25, "t2": 46.99}, {"p": "B", "sv": "Toppen! Vi ses på lördag. Hej då!", "en": "Great! See you on Saturday. Bye!", "t": 147.49, "t2": 54.78}], "q": [{"sv": "Varför ringer Lisa?", "en": "Why does Lisa call?", "o": ["Hon är sjuk", "Hon bjuder in till en fest", "Hon vill låna pengar"], "a": 1}, {"sv": "När kan vännen komma?", "en": "When can the friend come?", "o": ["Klockan sex", "Lite efter klockan sju", "På söndag"], "a": 1}, {"sv": "Vad ska vännen ta med?", "en": "What should the friend bring?", "o": ["Ingenting", "Mat", "Blommor"], "a": 0}]}, {"id": "l4", "theme": 2, "kind": "Dialog", "title_sv": "Vattenkokaren fungerar inte", "title_en": "The kettle doesn't work", "src": "audio/l4.mp3", "src_sv": "audio/l4-sv.mp3", "dur": 133.2, "dur_sv": 49.8, "lines": [{"p": "A", "sv": "Hej! Hur kan jag hjälpa dig?", "en": "Hi! How can I help you?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Hej! Jag köpte den här vattenkokaren förra veckan, men den fungerar inte.", "en": "Hi! I bought this kettle last week, but it doesn't work.", "t": 9.25, "t2": 3.99}, {"p": "A", "sv": "Oj, vad tråkigt. Vad är problemet?", "en": "Oh, how annoying. What is the problem?", "t": 25.2, "t2": 10.25}, {"p": "B", "sv": "Den blir inte varm. Vattnet kokar aldrig.", "en": "It doesn't get hot. The water never boils.", "t": 36.89, "t2": 14.65}, {"p": "A", "sv": "Har du kvittot?", "en": "Do you have the receipt?", "t": 49.59, "t2": 19.35}, {"p": "B", "sv": "Ja, här är det.", "en": "Yes, here it is.", "t": 55.95, "t2": 21.53}, {"p": "A", "sv": "Tack. Vill du byta den eller få pengarna tillbaka?", "en": "Thanks. Do you want to exchange it or get your money back?", "t": 62.66, "t2": 23.86}, {"p": "B", "sv": "Jag vill byta den mot en ny, tack.", "en": "I want to exchange it for a new one, please.", "t": 75.95, "t2": 28.69}, {"p": "A", "sv": "Det går bra. Vänta ett ögonblick, jag hämtar en ny.", "en": "That's fine. Wait a moment, I'll fetch a new one.", "t": 85.78, "t2": 32.13}, {"p": "A", "sv": "Varsågod! Den här är samma modell.", "en": "Here you are! This one is the same model.", "t": 100.47, "t2": 37.81}, {"p": "B", "sv": "Tack så mycket. Det var snabb service!", "en": "Thank you very much. That was fast service!", "t": 111.22, "t2": 41.75}, {"p": "A", "sv": "Ingen orsak. Ha en trevlig dag!", "en": "You're welcome. Have a nice day!", "t": 122.5, "t2": 45.72}], "q": [{"sv": "Vad är fel med vattenkokaren?", "en": "What is wrong with the kettle?", "o": ["Den läcker", "Den blir inte varm", "Den är för liten"], "a": 1}, {"sv": "Vad vill kunden?", "en": "What does the customer want?", "o": ["Pengarna tillbaka", "En ny vattenkokare", "En annan modell"], "a": 1}, {"sv": "Vad behöver kunden visa?", "en": "What does the customer need to show?", "o": ["Kvittot", "Ett ID-kort", "Ett bankkort"], "a": 0}]}, {"id": "l5", "theme": 2, "kind": "Dialog", "title_sv": "På restaurangen", "title_en": "At the restaurant", "src": "audio/l5.mp3", "src_sv": "audio/l5-sv.mp3", "dur": 139.5, "dur_sv": 51.8, "lines": [{"p": "A", "sv": "God kväll! Har ni bokat bord?", "en": "Good evening! Have you booked a table?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Nej, men har ni ett bord för två?", "en": "No, but do you have a table for two?", "t": 10.75, "t2": 4.56}, {"p": "A", "sv": "Ja, vid fönstret. Här är menyn.", "en": "Yes, by the window. Here is the menu.", "t": 19.66, "t2": 7.54}, {"p": "B", "sv": "Tack. Vad är dagens rätt?", "en": "Thanks. What is the dish of the day?", "t": 30.67, "t2": 11.54}, {"p": "A", "sv": "I dag har vi lax med potatis och sallad.", "en": "Today we have salmon with potatoes and salad.", "t": 40.4, "t2": 15.16}, {"p": "B", "sv": "Det låter gott. Jag tar laxen, och ett glas vatten.", "en": "That sounds good. I'll take the salmon, and a glass of water.", "t": 53.58, "t2": 20.12}, {"p": "A", "sv": "Varsågod, här är maten.", "en": "Here you are, here is the food.", "t": 67.83, "t2": 25.41}, {"p": "B", "sv": "Ursäkta, men maten är kall. Kan jag få en varm portion?", "en": "Excuse me, but the food is cold. Can I have a warm portion?", "t": 77.41, "t2": 28.91}, {"p": "A", "sv": "Förlåt! Jag tar den till köket direkt.", "en": "Sorry! I'll take it to the kitchen right away.", "t": 93.06, "t2": 34.57}, {"p": "A", "sv": "Här är en ny portion. Och kaffet är gratis i dag.", "en": "Here is a new portion. And the coffee is free today.", "t": 104.2, "t2": 38.67}, {"p": "B", "sv": "Tack, det var snällt. Kan jag betala med kort?", "en": "Thanks, that was kind. Can I pay by card?", "t": 119.4, "t2": 44.46}, {"p": "A", "sv": "Ja, självklart.", "en": "Yes, of course.", "t": 131.84, "t2": 48.97}], "q": [{"sv": "Vad äter kunden?", "en": "What does the customer eat?", "o": ["Kyckling", "Lax", "Soppa"], "a": 1}, {"sv": "Vad är problemet?", "en": "What is the problem?", "o": ["Maten är kall", "Maten är för dyr", "Det finns inget bord"], "a": 0}, {"sv": "Vad får kunden gratis?", "en": "What does the customer get for free?", "o": ["Efterrätt", "Vatten", "Kaffe"], "a": 2}]}, {"id": "l6", "theme": 3, "kind": "Berättelse", "title_sv": "En promenad i skogen", "title_en": "A walk in the forest", "src": "audio/l6.mp3", "src_sv": "audio/l6-sv.mp3", "dur": 142.7, "dur_sv": 51.7, "lines": [{"p": "A", "sv": "Jag heter Anna, och jag älskar naturen.", "en": "My name is Anna, and I love nature.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Nära mitt hus finns det en stor skog.", "en": "Near my house there is a big forest.", "t": 10.64, "t2": 4.16}, {"p": "A", "sv": "Jag promenerar där tre gånger i veckan.", "en": "I walk there three times a week.", "t": 21.43, "t2": 8.18}, {"p": "A", "sv": "På hösten plockar jag svamp och blåbär.", "en": "In autumn I pick mushrooms and blueberries.", "t": 31.29, "t2": 11.85}, {"p": "A", "sv": "I Finland får alla plocka bär i skogen. Det kallas allemansrätten.", "en": "In Finland everyone may pick berries in the forest. It is called the right of public access.", "t": 42.29, "t2": 15.68}, {"p": "A", "sv": "Men man får inte skräpa ner.", "en": "But you must not drop litter.", "t": 60.89, "t2": 22.13}, {"p": "A", "sv": "En dag såg jag en gammal soffa och många soppåsar bakom träden.", "en": "One day I saw an old sofa and many rubbish bags behind the trees.", "t": 69.95, "t2": 25.52}, {"p": "A", "sv": "Jag blev arg, för det är dåligt för naturen.", "en": "I got angry, because it's bad for nature.", "t": 87.14, "t2": 31.74}, {"p": "A", "sv": "Jag ringde kommunen och berättade det.", "en": "I called the municipality and told them.", "t": 99.04, "t2": 36.05}, {"p": "A", "sv": "Nästa vecka var skräpet borta.", "en": "The next week the rubbish was gone.", "t": 109.11, "t2": 39.55}, {"p": "A", "sv": "Nu är skogen ren och fin igen.", "en": "Now the forest is clean and nice again.", "t": 118.11, "t2": 42.76}, {"p": "A", "sv": "Naturen är viktig för mig, för där mår jag bra.", "en": "Nature is important to me, because I feel good there.", "t": 130.64, "t2": 47.47}], "q": [{"sv": "Hur ofta promenerar Anna i skogen?", "en": "How often does Anna walk in the forest?", "o": ["Varje dag", "Tre gånger i veckan", "En gång i månaden"], "a": 1}, {"sv": "Vad såg Anna bakom träden?", "en": "What did Anna see behind the trees?", "o": ["En soffa och soppåsar", "En bil", "Ett djur"], "a": 0}, {"sv": "Vem ringde Anna?", "en": "Who did Anna call?", "o": ["Polisen", "Kommunen", "En vän"], "a": 1}]}, {"id": "l7", "theme": 3, "kind": "Dialog", "title_sv": "Sopsortering", "title_en": "Sorting rubbish", "src": "audio/l7.mp3", "src_sv": "audio/l7-sv.mp3", "dur": 133.5, "dur_sv": 49.0, "lines": [{"p": "A", "sv": "Hej! Ursäkta, kan jag fråga en sak?", "en": "Hi! Excuse me, can I ask something?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Ja, visst.", "en": "Yes, sure.", "t": 11.77, "t2": 4.8}, {"p": "A", "sv": "Jag är ny i huset. Hur sorterar man soporna här?", "en": "I'm new in the building. How do you sort the rubbish here?", "t": 17.34, "t2": 6.66}, {"p": "B", "sv": "Det är lätt. Det finns fem kärl på gården.", "en": "It's easy. There are five bins in the yard.", "t": 30.98, "t2": 11.86}, {"p": "B", "sv": "Ett för papper, ett för kartong, ett för plast, ett för glas och ett för bioavfall.", "en": "One for paper, one for cardboard, one for plastic, one for glass and one for biowaste.", "t": 42.35, "t2": 15.95}, {"p": "A", "sv": "Och var slänger man gamla batterier?", "en": "And where do you throw old batteries?", "t": 61.63, "t2": 22.36}, {"p": "B", "sv": "Batterier lämnar man i affären. Det finns en låda vid dörren.", "en": "You leave batteries in the shop. There is a box by the door.", "t": 71.41, "t2": 25.85}, {"p": "A", "sv": "Och stora saker, till exempel en gammal stol?", "en": "And big things, for example an old chair?", "t": 87.59, "t2": 32.02}, {"p": "B", "sv": "Dem tar man till återvinningscentralen.", "en": "You take them to the recycling centre.", "t": 100.45, "t2": 36.81}, {"p": "A", "sv": "Tack så mycket! Nu förstår jag.", "en": "Thank you very much! Now I understand.", "t": 111.75, "t2": 41.15}, {"p": "B", "sv": "Ingen orsak. Det är bra för miljön.", "en": "You're welcome. It's good for the environment.", "t": 121.4, "t2": 44.44}], "q": [{"sv": "Hur många kärl finns det på gården?", "en": "How many bins are there in the yard?", "o": ["Tre", "Fem", "Sju"], "a": 1}, {"sv": "Var lämnar man batterier?", "en": "Where do you leave batteries?", "o": ["I affären", "På gården", "I källaren"], "a": 0}, {"sv": "Vart tar man en gammal stol?", "en": "Where do you take an old chair?", "o": ["Till skogen", "Till återvinningscentralen", "Till grannen"], "a": 1}]}, {"id": "l8", "theme": 4, "kind": "Telefonsamtal", "title_sv": "Ringa hälsocentralen", "title_en": "Calling the health centre", "src": "audio/l8.mp3", "src_sv": "audio/l8-sv.mp3", "dur": 137.7, "dur_sv": 51.1, "lines": [{"p": "A", "sv": "Hälsocentralen, det är Maria.", "en": "Health centre, this is Maria.", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Hej, jag heter Alex Andersson. Jag ringer för att jag är sjuk.", "en": "Hello, my name is Alex Andersson. I'm calling because I'm ill.", "t": 10.83, "t2": 4.46}, {"p": "A", "sv": "Vad har du för symtom?", "en": "What symptoms do you have?", "t": 25.15, "t2": 9.46}, {"p": "B", "sv": "Jag har ont i halsen och feber.", "en": "I have a sore throat and a fever.", "t": 32.54, "t2": 12.09}, {"p": "A", "sv": "Hur länge har du haft feber?", "en": "How long have you had a fever?", "t": 42.83, "t2": 15.92}, {"p": "B", "sv": "I tre dagar. I går hade jag trettioåtta och fem.", "en": "For three days. Yesterday I had thirty-eight point five.", "t": 50.53, "t2": 18.65}, {"p": "A", "sv": "Okej. Du kan få en tid hos läkaren i morgon klockan tio.", "en": "OK. You can get an appointment with the doctor tomorrow at ten.", "t": 65.67, "t2": 24.39}, {"p": "B", "sv": "Tyvärr jobbar jag då. Finns det en tid på eftermiddagen?", "en": "Unfortunately I work then. Is there a time in the afternoon?", "t": 82.49, "t2": 30.81}, {"p": "A", "sv": "Ja, klockan två. Passar det?", "en": "Yes, at two. Does that suit you?", "t": 96.81, "t2": 35.96}, {"p": "B", "sv": "Ja, det passar bra. Tack!", "en": "Yes, that suits me. Thanks!", "t": 106.47, "t2": 39.36}, {"p": "A", "sv": "Ta med ditt FPA-kort. Och drick mycket vatten.", "en": "Bring your Kela card. And drink a lot of water.", "t": 116.47, "t2": 43.09}, {"p": "B", "sv": "Det ska jag göra. Hej då!", "en": "I will. Bye!", "t": 129.4, "t2": 47.86}], "q": [{"sv": "Vad har Alex?", "en": "What does Alex have?", "o": ["Ont i ryggen", "Ont i halsen och feber", "Huvudvärk"], "a": 1}, {"sv": "Vilken tid får Alex?", "en": "What time does Alex get?", "o": ["Klockan tio", "Klockan två", "Klockan fyra"], "a": 1}, {"sv": "Vad ska Alex ta med?", "en": "What should Alex bring?", "o": ["Sitt FPA-kort", "Medicin", "Ett intyg"], "a": 0}]}, {"id": "l9", "theme": 4, "kind": "Dialog", "title_sv": "Hos läkaren", "title_en": "At the doctor's", "src": "audio/l9.mp3", "src_sv": "audio/l9-sv.mp3", "dur": 134.2, "dur_sv": 49.7, "lines": [{"p": "A", "sv": "Hej, välkommen in. Hur mår du i dag?", "en": "Hi, welcome in. How are you today?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Inte så bra. Jag har ont i ryggen.", "en": "Not so good. I have back pain.", "t": 12.1, "t2": 5.0}, {"p": "A", "sv": "När började det?", "en": "When did it start?", "t": 24.0, "t2": 9.5}, {"p": "B", "sv": "För en vecka sedan. Jag bar en tung låda på jobbet.", "en": "A week ago. I carried a heavy box at work.", "t": 30.83, "t2": 11.96}, {"p": "A", "sv": "Gör det ont när du går?", "en": "Does it hurt when you walk?", "t": 43.88, "t2": 16.83}, {"p": "B", "sv": "Ja, och när jag sitter länge.", "en": "Yes, and when I sit for a long time.", "t": 52.25, "t2": 19.93}, {"p": "A", "sv": "Jag undersöker dig nu. Böj dig framåt, tack.", "en": "I'll examine you now. Bend forward, please.", "t": 60.37, "t2": 22.49}, {"p": "A", "sv": "Det är inget farligt. Musklerna är trötta.", "en": "It's nothing dangerous. The muscles are tired.", "t": 73.24, "t2": 27.33}, {"p": "A", "sv": "Du får medicin mot smärta, och du ska vila i tre dagar.", "en": "You get medicine for the pain, and you should rest for three days.", "t": 86.79, "t2": 32.42}, {"p": "B", "sv": "Behöver jag ett läkarintyg till jobbet?", "en": "Do I need a doctor's certificate for work?", "t": 101.6, "t2": 37.87}, {"p": "A", "sv": "Ja, jag skriver ett intyg. Och rör på dig lite varje dag.", "en": "Yes, I'll write a certificate. And move a little every day.", "t": 112.38, "t2": 41.78}, {"p": "B", "sv": "Tack, doktorn!", "en": "Thank you, doctor!", "t": 127.89, "t2": 47.49}], "q": [{"sv": "Varför har patienten ont i ryggen?", "en": "Why does the patient have back pain?", "o": ["Han ramlade", "Han bar en tung låda", "Han sprang"], "a": 1}, {"sv": "Hur länge ska patienten vila?", "en": "How long should the patient rest?", "o": ["En dag", "Tre dagar", "Två veckor"], "a": 1}, {"sv": "Vad skriver läkaren?", "en": "What does the doctor write?", "o": ["Ett recept på glasögon", "Ett läkarintyg", "En räkning"], "a": 1}]}, {"id": "l10", "theme": 5, "kind": "Intervju", "title_sv": "En arbetsintervju", "title_en": "A job interview", "src": "audio/l10.mp3", "src_sv": "audio/l10-sv.mp3", "dur": 167.2, "dur_sv": 61.9, "lines": [{"p": "A", "sv": "Välkommen! Jag heter Petra och jag är chef här på restaurangen.", "en": "Welcome! My name is Petra and I'm the manager here at the restaurant.", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Tack. Jag heter Ali.", "en": "Thanks. My name is Ali.", "t": 15.28, "t2": 5.93}, {"p": "A", "sv": "Berätta lite om dig själv.", "en": "Tell me a little about yourself.", "t": 24.25, "t2": 9.23}, {"p": "B", "sv": "Jag är tjugoåtta år och kommer från Syrien. Jag har bott i Finland i fyra år.", "en": "I'm twenty-eight and come from Syria. I have lived in Finland for four years.", "t": 33.02, "t2": 12.39}, {"p": "A", "sv": "Vad har du jobbat med tidigare?", "en": "What have you worked with before?", "t": 52.35, "t2": 19.72}, {"p": "B", "sv": "I mitt hemland jobbade jag som kock i fem år.", "en": "In my home country I worked as a cook for five years.", "t": 60.98, "t2": 22.95}, {"p": "A", "sv": "Vad är du bra på?", "en": "What are you good at?", "t": 73.95, "t2": 27.67}, {"p": "B", "sv": "Jag är snabb och noggrann, och jag tycker om att jobba i grupp.", "en": "I'm fast and careful, and I like working in a team.", "t": 80.12, "t2": 29.84}, {"p": "A", "sv": "Kan du jobba på kvällar och helger?", "en": "Can you work evenings and weekends?", "t": 93.91, "t2": 34.88}, {"p": "B", "sv": "Ja, det går bra.", "en": "Yes, that's fine.", "t": 103.39, "t2": 38.24}, {"p": "A", "sv": "Har du några frågor?", "en": "Do you have any questions?", "t": 111.51, "t2": 41.23}, {"p": "B", "sv": "Ja. När börjar jobbet, och hur många timmar i veckan är det?", "en": "Yes. When does the job start, and how many hours a week is it?", "t": 119.97, "t2": 44.47}, {"p": "A", "sv": "Jobbet börjar i december, och det är trettio timmar i veckan.", "en": "The job starts in December, and it's thirty hours a week.", "t": 135.42, "t2": 50.21}, {"p": "A", "sv": "Tack för att du kom. Jag ringer dig på fredag.", "en": "Thanks for coming. I'll call you on Friday.", "t": 150.8, "t2": 55.93}, {"p": "B", "sv": "Tack själv!", "en": "Thank you!", "t": 161.27, "t2": 59.73}], "q": [{"sv": "Vad jobbade Ali med i sitt hemland?", "en": "What did Ali work as in his home country?", "o": ["Lärare", "Kock", "Busschaufför"], "a": 1}, {"sv": "När börjar jobbet?", "en": "When does the job start?", "o": ["I december", "I januari", "I morgon"], "a": 0}, {"sv": "När ringer Petra?", "en": "When will Petra call?", "o": ["I morgon", "På fredag", "Nästa månad"], "a": 1}]}, {"id": "l11", "theme": 5, "kind": "Dialog", "title_sv": "Första dagen på jobbet", "title_en": "The first day at work", "src": "audio/l11.mp3", "src_sv": "audio/l11-sv.mp3", "dur": 129.4, "dur_sv": 48.7, "lines": [{"p": "A", "sv": "Hej och välkommen! Jag heter Johan. Jag ska visa dig runt.", "en": "Hi and welcome! My name is Johan. I'll show you around.", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Tack! Jag heter Ella. Jag är lite nervös.", "en": "Thanks! My name is Ella. I'm a bit nervous.", "t": 16.14, "t2": 6.39}, {"p": "A", "sv": "Det är normalt. Här är kafferummet. Kaffet är gratis.", "en": "That's normal. Here is the coffee room. The coffee is free.", "t": 29.45, "t2": 11.35}, {"p": "B", "sv": "Vad bra! När har vi lunch?", "en": "How nice! When do we have lunch?", "t": 46.17, "t2": 17.71}, {"p": "A", "sv": "Lunchen är klockan elva. Den är trettio minuter.", "en": "Lunch is at eleven. It is thirty minutes.", "t": 56.16, "t2": 21.29}, {"p": "A", "sv": "Och här är ditt skåp och dina arbetskläder.", "en": "And here is your locker and your work clothes.", "t": 69.97, "t2": 26.67}, {"p": "B", "sv": "Var finns toaletten?", "en": "Where is the toilet?", "t": 82.19, "t2": 31.19}, {"p": "A", "sv": "Till vänster, vid trappan.", "en": "On the left, by the stairs.", "t": 89.86, "t2": 34.08}, {"p": "A", "sv": "Om du har problem, kan du alltid fråga mig.", "en": "If you have problems, you can always ask me.", "t": 98.24, "t2": 37.03}, {"p": "B", "sv": "Tack, det är snällt av dig.", "en": "Thanks, that's kind of you.", "t": 109.83, "t2": 41.21}, {"p": "A", "sv": "Ingen orsak. Lycka till i dag!", "en": "You're welcome. Good luck today!", "t": 118.88, "t2": 44.62}], "q": [{"sv": "Hur känner sig Ella?", "en": "How does Ella feel?", "o": ["Trött", "Nervös", "Arg"], "a": 1}, {"sv": "När är lunchen?", "en": "When is lunch?", "o": ["Klockan elva", "Klockan tolv", "Klockan ett"], "a": 0}, {"sv": "Var är toaletten?", "en": "Where is the toilet?", "o": ["Till höger", "Vid kafferummet", "Till vänster, vid trappan"], "a": 2}]}, {"id": "l12", "theme": 6, "kind": "Dialog", "title_sv": "Hur var helgen?", "title_en": "How was the weekend?", "src": "audio/l12.mp3", "src_sv": "audio/l12-sv.mp3", "dur": 127.6, "dur_sv": 46.8, "lines": [{"p": "A", "sv": "Hej Pekka! Hur var helgen?", "en": "Hi Pekka! How was the weekend?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Den var jättefin, tack. Vi var på vår stuga.", "en": "It was really nice, thanks. We were at our cottage.", "t": 10.22, "t2": 4.24}, {"p": "A", "sv": "Var ligger stugan?", "en": "Where is the cottage?", "t": 23.92, "t2": 9.19}, {"p": "B", "sv": "Vid en sjö, ungefär två timmar från Helsingfors.", "en": "By a lake, about two hours from Helsinki.", "t": 31.15, "t2": 11.82}, {"p": "A", "sv": "Vad gjorde ni där?", "en": "What did you do there?", "t": 44.64, "t2": 16.81}, {"p": "B", "sv": "Vi badade bastu och simmade i sjön. Vattnet var kallt!", "en": "We had a sauna and swam in the lake. The water was cold!", "t": 51.28, "t2": 19.24}, {"p": "B", "sv": "På lördagen fiskade jag med min son.", "en": "On Saturday I went fishing with my son.", "t": 67.22, "t2": 25.16}, {"p": "A", "sv": "Fick ni någon fisk?", "en": "Did you catch any fish?", "t": 76.93, "t2": 28.49}, {"p": "B", "sv": "Ja, tre små abborrar. Vi grillade dem på kvällen.", "en": "Yes, three small perch. We grilled them in the evening.", "t": 83.96, "t2": 31.04}, {"p": "A", "sv": "Det låter mysigt. Jag var bara hemma och städade.", "en": "That sounds cosy. I was just at home cleaning.", "t": 98.82, "t2": 36.55}, {"p": "B", "sv": "Du får gärna följa med nästa gång!", "en": "You're welcome to come along next time!", "t": 111.78, "t2": 41.45}, {"p": "A", "sv": "Tack, gärna!", "en": "Thanks, I'd love to!", "t": 121.24, "t2": 44.75}], "q": [{"sv": "Var var Pekka i helgen?", "en": "Where was Pekka at the weekend?", "o": ["Hemma", "På stugan", "I Stockholm"], "a": 1}, {"sv": "Vad gjorde Pekka på lördagen?", "en": "What did Pekka do on Saturday?", "o": ["Han fiskade", "Han jobbade", "Han städade"], "a": 0}, {"sv": "Vad gjorde den andra personen i helgen?", "en": "What did the other person do at the weekend?", "o": ["Reste", "Städade hemma", "Var sjuk"], "a": 1}]}, {"id": "l13", "theme": 6, "kind": "Dialog", "title_sv": "Ett lånekort på biblioteket", "title_en": "A library card", "src": "audio/l13.mp3", "src_sv": "audio/l13-sv.mp3", "dur": 135.1, "dur_sv": 49.9, "lines": [{"p": "A", "sv": "Hej! Jag vill gärna låna böcker. Hur får jag ett lånekort?", "en": "Hi! I'd like to borrow books. How do I get a library card?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Det är gratis. Har du ett ID-kort eller pass med dig?", "en": "It's free. Do you have an ID card or passport with you?", "t": 15.09, "t2": 5.95}, {"p": "A", "sv": "Ja, här är mitt ID-kort.", "en": "Yes, here is my ID card.", "t": 30.99, "t2": 11.97}, {"p": "B", "sv": "Tack. Fyll i den här blanketten med namn, adress och telefonnummer.", "en": "Thanks. Fill in this form with name, address and phone number.", "t": 40.22, "t2": 15.22}, {"p": "A", "sv": "Okej. Hur länge får man låna en bok?", "en": "OK. How long can you borrow a book?", "t": 56.78, "t2": 21.34}, {"p": "B", "sv": "I fyra veckor. Du kan förnya lånet på nätet.", "en": "For four weeks. You can renew the loan online.", "t": 67.63, "t2": 25.4}, {"p": "A", "sv": "Har ni böcker på lätt svenska?", "en": "Do you have books in easy Swedish?", "t": 81.83, "t2": 30.8}, {"p": "B", "sv": "Ja, de finns på hyllan där borta, vid fönstret.", "en": "Yes, they are on the shelf over there, by the window.", "t": 90.23, "t2": 33.71}, {"p": "A", "sv": "Vad händer om jag tappar kortet?", "en": "What happens if I lose the card?", "t": 102.16, "t2": 37.9}, {"p": "B", "sv": "Då ringer du oss, och du får ett nytt kort. Det kostar två euro.", "en": "Then you call us, and you get a new card. It costs two euros.", "t": 111.21, "t2": 41.08}, {"p": "A", "sv": "Tack för hjälpen!", "en": "Thanks for the help!", "t": 128.3, "t2": 47.36}], "q": [{"sv": "Vad kostar ett lånekort?", "en": "How much does a library card cost?", "o": ["Det är gratis", "Två euro", "Fem euro"], "a": 0}, {"sv": "Hur länge får man låna en bok?", "en": "How long can you borrow a book?", "o": ["En vecka", "Två veckor", "Fyra veckor"], "a": 2}, {"sv": "Vad kostar ett nytt kort om man tappar det?", "en": "What does a new card cost if you lose it?", "o": ["Ingenting", "Två euro", "Tio euro"], "a": 1}]}, {"id": "l14", "theme": 7, "kind": "Dialog", "title_sv": "Jag har tappat mitt pass", "title_en": "I have lost my passport", "src": "audio/l14.mp3", "src_sv": "audio/l14-sv.mp3", "dur": 131.8, "dur_sv": 48.9, "lines": [{"p": "A", "sv": "Hej, välkommen till polisen. Vad gäller ärendet?", "en": "Hello, welcome to the police. What is your business?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Hej. Jag har tappat mitt pass.", "en": "Hello. I have lost my passport.", "t": 14.32, "t2": 5.76}, {"p": "A", "sv": "När och var tappade du det?", "en": "When and where did you lose it?", "t": 24.04, "t2": 9.16}, {"p": "B", "sv": "Jag tror att jag tappade det på bussen i går kväll.", "en": "I think I lost it on the bus last night.", "t": 32.21, "t2": 12.19}, {"p": "A", "sv": "Har du ringt bussbolaget?", "en": "Have you called the bus company?", "t": 43.28, "t2": 16.24}, {"p": "B", "sv": "Ja, men de har inte hittat det.", "en": "Yes, but they haven't found it.", "t": 52.3, "t2": 19.55}, {"p": "A", "sv": "Okej. Då gör vi en anmälan, och du ansöker om ett nytt pass.", "en": "OK. Then we make a report, and you apply for a new passport.", "t": 62.17, "t2": 23.34}, {"p": "B", "sv": "Hur ansöker jag?", "en": "How do I apply?", "t": 78.5, "t2": 29.33}, {"p": "A", "sv": "Du kan ansöka på nätet. Sedan kommer du hit, och vi tar ett foto och fingeravtryck.", "en": "You can apply online. Then you come here, and we take a photo and fingerprints.", "t": 86.04, "t2": 32.11}, {"p": "B", "sv": "Hur länge tar det?", "en": "How long does it take?", "t": 105.6, "t2": 39.4}, {"p": "A", "sv": "Ungefär två veckor. Passet kommer med posten.", "en": "About two weeks. The passport comes by post.", "t": 111.93, "t2": 41.55}, {"p": "B", "sv": "Tack för hjälpen.", "en": "Thanks for the help.", "t": 125.28, "t2": 46.44}], "q": [{"sv": "Var tappade personen passet?", "en": "Where did the person lose the passport?", "o": ["På tåget", "På bussen", "I affären"], "a": 1}, {"sv": "Hur ansöker man om ett nytt pass?", "en": "How do you apply for a new passport?", "o": ["På nätet", "Med brev", "Hos banken"], "a": 0}, {"sv": "Hur länge tar det att få ett nytt pass?", "en": "How long does it take to get a new passport?", "o": ["Två dagar", "Två veckor", "Två månader"], "a": 1}]}, {"id": "l15", "theme": 7, "kind": "Telefonsamtal", "title_sv": "Ringa FPA", "title_en": "Calling Kela", "src": "audio/l15.mp3", "src_sv": "audio/l15-sv.mp3", "dur": 140.0, "dur_sv": 51.5, "lines": [{"p": "A", "sv": "FPA, du talar med Tiina. Hur kan jag hjälpa dig?", "en": "Kela, you are speaking with Tiina. How can I help you?", "t": 0.8, "t2": 0.8}, {"p": "B", "sv": "Hej, jag heter Sara Ahmed. Jag ringer om mitt bostadsbidrag.", "en": "Hello, my name is Sara Ahmed. I'm calling about my housing allowance.", "t": 13.74, "t2": 5.51}, {"p": "A", "sv": "Vad är problemet?", "en": "What is the problem?", "t": 31.42, "t2": 12.05}, {"p": "B", "sv": "Jag har inte fått pengarna den här månaden.", "en": "I haven't received the money this month.", "t": 38.61, "t2": 14.72}, {"p": "A", "sv": "Kan jag få ditt personnummer?", "en": "Can I have your personal identity code?", "t": 49.72, "t2": 18.88}, {"p": "B", "sv": "Ja, det är ett, två, noll, tre, åtta, fem.", "en": "Yes, it's one, two, zero, three, eight, five.", "t": 57.85, "t2": 21.6}, {"p": "A", "sv": "Tack. Jag ser att din hyra har ändrats. Vi behöver ditt nya hyreskontrakt.", "en": "Thanks. I see that your rent has changed. We need your new rental contract.", "t": 73.9, "t2": 27.24}, {"p": "B", "sv": "Jaha. Hur skickar jag det?", "en": "I see. How do I send it?", "t": 92.39, "t2": 34.33}, {"p": "A", "sv": "Du kan skicka det på nätet, i vår e-tjänst.", "en": "You can send it online, in our e-service.", "t": 101.15, "t2": 37.54}, {"p": "B", "sv": "När får jag pengarna?", "en": "When will I get the money?", "t": 112.23, "t2": 41.49}, {"p": "A", "sv": "Ungefär en vecka efter att vi har fått kontraktet.", "en": "About a week after we have received the contract.", "t": 118.86, "t2": 43.76}, {"p": "B", "sv": "Tack så mycket. Hej då!", "en": "Thank you very much. Bye!", "t": 132.15, "t2": 48.72}], "q": [{"sv": "Varför ringer Sara?", "en": "Why does Sara call?", "o": ["Hon vill ha ett nytt jobb", "Hon har inte fått sitt bostadsbidrag", "Hon har flyttat utomlands"], "a": 1}, {"sv": "Vad behöver FPA?", "en": "What does Kela need?", "o": ["Hennes nya hyreskontrakt", "Hennes pass", "Ett läkarintyg"], "a": 0}, {"sv": "Hur skickar hon det?", "en": "How does she send it?", "o": ["Med posten", "På nätet", "Hon tar det till kontoret"], "a": 1}]}, {"id": "l16", "theme": 6, "kind": "Röster", "title_sv": "Vad ska du göra i sommar?", "title_en": "What will you do this summer?", "src": "audio/l16.mp3", "src_sv": "audio/l16-sv.mp3", "dur": 119.5, "dur_sv": 44.3, "lines": [{"p": "A", "sv": "Jag heter Mona. I sommar ska jag jobba i juni och juli.", "en": "My name is Mona. This summer I'll work in June and July.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "I augusti har jag semester. Då ska jag resa till mitt hemland och träffa min familj.", "en": "In August I have holiday. Then I'll travel to my home country and see my family.", "t": 15.96, "t2": 6.17}, {"p": "B", "sv": "Jag heter Karim. Jag ska stanna i Finland hela sommaren.", "en": "My name is Karim. I'll stay in Finland all summer.", "t": 36.38, "t2": 13.86}, {"p": "B", "sv": "Jag ska cykla mycket, och jag ska lära mig att simma.", "en": "I'll cycle a lot, and I'll learn to swim.", "t": 51.59, "t2": 19.55}, {"p": "A", "sv": "Jag heter Liisa. Jag ska hyra en stuga med mina vänner i en vecka.", "en": "My name is Liisa. I'll rent a cottage with my friends for a week.", "t": 63.54, "t2": 23.96}, {"p": "A", "sv": "Vi ska bada, grilla och vila. Jag längtar!", "en": "We'll swim, have barbecues and rest. I can't wait!", "t": 80.43, "t2": 30.4}, {"p": "B", "sv": "Jag heter Daniel. Jag ska gå en sommarkurs i svenska.", "en": "My name is Daniel. I'll take a summer course in Swedish.", "t": 93.39, "t2": 34.9}, {"p": "B", "sv": "Jag vill klara YKI-testet i höst.", "en": "I want to pass the YKI test in the autumn.", "t": 108.36, "t2": 40.39}], "q": [{"sv": "Vad ska Mona göra i augusti?", "en": "What will Mona do in August?", "o": ["Jobba", "Resa till sitt hemland", "Gå en kurs"], "a": 1}, {"sv": "Vad ska Karim lära sig?", "en": "What will Karim learn?", "o": ["Att simma", "Att cykla", "Svenska"], "a": 0}, {"sv": "Varför går Daniel en sommarkurs?", "en": "Why does Daniel take a summer course?", "o": ["Han vill klara YKI-testet", "Han är lärare", "Han har tråkigt"], "a": 0}]}, {"id": "s1", "theme": 1, "kind": "Färdig berättelse", "title_sv": "Ett minne: min första vinter", "title_en": "A memory: my first winter", "src": "audio/s1.mp3", "src_sv": "audio/s1-sv.mp3", "dur": 96.5, "dur_sv": 35.9, "lines": [{"p": "A", "sv": "Jag ska berätta om ett minne.", "en": "I'm going to tell about a memory.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Det var min första vinter i Finland, för sex år sedan.", "en": "It was my first winter in Finland, six years ago.", "t": 9.08, "t2": 3.72}, {"p": "A", "sv": "En morgon tittade jag ut, och allt var vitt.", "en": "One morning I looked out, and everything was white.", "t": 22.63, "t2": 8.75}, {"p": "A", "sv": "Först blev jag glad, och jag gick ut och tog bilder.", "en": "First I was happy, and I went out and took pictures.", "t": 33.75, "t2": 12.7}, {"p": "A", "sv": "Sedan halkade jag och föll i snön, och alla skrattade.", "en": "Then I slipped and fell in the snow, and everyone laughed.", "t": 46.82, "t2": 17.4}, {"p": "A", "sv": "Det var kallt, men det var en rolig dag.", "en": "It was cold, but it was a fun day.", "t": 61.38, "t2": 22.8}, {"p": "A", "sv": "I mitt hemland finns det ingen snö, så jag glömmer aldrig den dagen.", "en": "In my home country there is no snow, so I'll never forget that day.", "t": 74.3, "t2": 27.77}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 90.67, "t2": 33.71}], "q": [{"sv": "Vad hände när Alex gick ut?", "en": "What happened when Alex went out?", "o": ["Han halkade och föll i snön", "Han tappade telefonen", "Han blev sjuk"], "a": 0}, {"sv": "Varför glömmer hen aldrig dagen?", "en": "Why will he never forget the day?", "o": ["Det finns ingen snö i hemlandet", "Det var hans födelsedag", "Han fick ett jobb"], "a": 0}]}, {"id": "s2", "theme": 1, "kind": "Färdig berättelse", "title_sv": "En person: min vän Sara", "title_en": "A person: my friend Sara", "src": "audio/s2.mp3", "src_sv": "audio/s2-sv.mp3", "dur": 76.8, "dur_sv": 28.9, "lines": [{"p": "A", "sv": "Jag ska berätta om min vän Sara.", "en": "I'm going to tell about my friend Sara.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Hon är trettio år och jobbar som lärare.", "en": "She is thirty and works as a teacher.", "t": 10.87, "t2": 4.52}, {"p": "A", "sv": "Hon är snäll, rolig och hjälpsam.", "en": "She is kind, funny and helpful.", "t": 22.62, "t2": 8.93}, {"p": "A", "sv": "Vi träffades på en svenskkurs för fem år sedan.", "en": "We met on a Swedish course five years ago.", "t": 32.91, "t2": 12.57}, {"p": "A", "sv": "Till exempel hjälpte hon mig när jag flyttade och när jag sökte jobb.", "en": "For example, she helped me when I moved and when I was looking for a job.", "t": 45.3, "t2": 17.19}, {"p": "A", "sv": "Därför är hon viktig för mig.", "en": "That's why she is important to me.", "t": 62.09, "t2": 23.41}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 70.97, "t2": 26.68}], "q": [{"sv": "Var träffades de?", "en": "Where did they meet?", "o": ["På jobbet", "På en svenskkurs", "I skolan"], "a": 1}, {"sv": "Vad jobbar Sara som?", "en": "What does Sara work as?", "o": ["Lärare", "Läkare", "Kock"], "a": 0}]}, {"id": "s3", "theme": 1, "kind": "Färdig berättelse", "title_sv": "En plats: mitt hem", "title_en": "A place: my home", "src": "audio/s3.mp3", "src_sv": "audio/s3-sv.mp3", "dur": 90.7, "dur_sv": 33.5, "lines": [{"p": "A", "sv": "Jag ska berätta om mitt hem.", "en": "I'm going to tell about my home.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Jag bor i en tvåa i Vanda med min familj.", "en": "I live in a two-room flat in Vantaa with my family.", "t": 9.04, "t2": 3.73}, {"p": "A", "sv": "Det finns ett sovrum, ett vardagsrum, ett kök och en liten balkong.", "en": "There is a bedroom, a living room, a kitchen and a small balcony.", "t": 20.97, "t2": 7.79}, {"p": "A", "sv": "Nära huset finns en skog, en affär och en busshållplats.", "en": "Near the house there is a forest, a shop and a bus stop.", "t": 38.65, "t2": 14.4}, {"p": "A", "sv": "Det bästa är att det är lugnt och tryggt.", "en": "The best thing is that it's quiet and safe.", "t": 53.3, "t2": 19.73}, {"p": "A", "sv": "Det svåraste är att köket är litet.", "en": "The hardest thing is that the kitchen is small.", "t": 65.43, "t2": 24.21}, {"p": "A", "sv": "Därför trivs jag här.", "en": "That's why I like it here.", "t": 77.07, "t2": 28.49}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 84.9, "t2": 31.33}], "q": [{"sv": "Var bor personen?", "en": "Where does the person live?", "o": ["I Vanda", "I Åbo", "I Esbo"], "a": 0}, {"sv": "Vad är det svåraste?", "en": "What is the hardest thing?", "o": ["Köket är litet", "Det är långt till bussen", "Grannarna är högljudda"], "a": 0}]}, {"id": "s4", "theme": 6, "kind": "Färdig berättelse", "title_sv": "En resa: en helg på stugan", "title_en": "A trip: a weekend at the cottage", "src": "audio/s4.mp3", "src_sv": "audio/s4-sv.mp3", "dur": 84.3, "dur_sv": 31.0, "lines": [{"p": "A", "sv": "Jag ska berätta om en resa.", "en": "I'm going to tell about a trip.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "I somras åkte vi till en stuga vid en sjö.", "en": "Last summer we went to a cottage by a lake.", "t": 9.18, "t2": 3.84}, {"p": "A", "sv": "Först badade vi och grillade.", "en": "First we swam and had a barbecue.", "t": 21.48, "t2": 8.4}, {"p": "A", "sv": "Sedan gick vi i bastu, och på kvällen satt vi ute, för det var ljust hela natten.", "en": "Then we had a sauna, and in the evening we sat outside, because it was light all night.", "t": 30.98, "t2": 11.71}, {"p": "A", "sv": "Det bästa var tystnaden och naturen.", "en": "The best thing was the quiet and the nature.", "t": 48.79, "t2": 18.03}, {"p": "A", "sv": "Det svåraste var myggorna!", "en": "The hardest thing was the mosquitoes!", "t": 60.29, "t2": 22.27}, {"p": "A", "sv": "Därför vill jag åka dit igen.", "en": "That's why I want to go there again.", "t": 69.47, "t2": 25.46}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 78.48, "t2": 28.76}], "q": [{"sv": "Var låg stugan?", "en": "Where was the cottage?", "o": ["Vid havet", "Vid en sjö", "I staden"], "a": 1}, {"sv": "Vad var det svåraste?", "en": "What was the hardest thing?", "o": ["Myggorna", "Kylan", "Regnet"], "a": 0}]}, {"id": "s5", "theme": 1, "kind": "Färdig berättelse", "title_sv": "En fest: min sons födelsedag", "title_en": "A party: my son's birthday", "src": "audio/s5.mp3", "src_sv": "audio/s5-sv.mp3", "dur": 86.5, "dur_sv": 32.0, "lines": [{"p": "A", "sv": "Jag ska berätta om en fest.", "en": "I'm going to tell about a party.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "I maj fyllde min son sju år.", "en": "In May my son turned seven.", "t": 9.32, "t2": 3.88}, {"p": "A", "sv": "Vi bjöd hem hans vänner och vår familj.", "en": "We invited his friends and our family home.", "t": 19.34, "t2": 7.62}, {"p": "A", "sv": "Först åt vi tårta, och sedan lekte barnen i parken.", "en": "First we had cake, and then the children played in the park.", "t": 30.99, "t2": 11.85}, {"p": "A", "sv": "Han fick en ny cykel och blev jätteglad.", "en": "He got a new bike and was really happy.", "t": 44.29, "t2": 16.53}, {"p": "A", "sv": "Det bästa var att alla var tillsammans.", "en": "The best thing was that everyone was together.", "t": 55.25, "t2": 20.63}, {"p": "A", "sv": "I mitt hemland är fester större, men här är de lugnare.", "en": "In my home country parties are bigger, but here they are calmer.", "t": 65.19, "t2": 24.13}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 80.67, "t2": 29.83}], "q": [{"sv": "Hur gammal blev sonen?", "en": "How old did the son turn?", "o": ["Fem", "Sju", "Tio"], "a": 1}, {"sv": "Vad fick han?", "en": "What did he get?", "o": ["En cykel", "En dator", "En hund"], "a": 0}]}, {"id": "s6", "theme": 4, "kind": "Färdig berättelse", "title_sv": "Ett problem: jag bröt armen", "title_en": "A problem: I broke my arm", "src": "audio/s6.mp3", "src_sv": "audio/s6-sv.mp3", "dur": 90.5, "dur_sv": 33.4, "lines": [{"p": "A", "sv": "Jag ska berätta om en olycka.", "en": "I'm going to tell about an accident.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "För två år sedan halkade jag på isen och bröt armen.", "en": "Two years ago I slipped on the ice and broke my arm.", "t": 9.67, "t2": 3.87}, {"p": "A", "sv": "Först gick jag till hälsocentralen, och sedan åkte jag till sjukhuset.", "en": "First I went to the health centre, and then I went to the hospital.", "t": 23.08, "t2": 8.66}, {"p": "A", "sv": "Jag hade gips i sex veckor och kunde inte jobba.", "en": "I had a cast for six weeks and couldn't work.", "t": 38.35, "t2": 14.36}, {"p": "A", "sv": "Min familj och mina vänner hjälpte mig mycket.", "en": "My family and my friends helped me a lot.", "t": 52.61, "t2": 19.84}, {"p": "A", "sv": "Nu går jag försiktigt på vintern.", "en": "Now I walk carefully in winter.", "t": 64.66, "t2": 24.32}, {"p": "A", "sv": "Därför vet jag att hälsan är viktigast.", "en": "That's why I know that health is most important.", "t": 73.87, "t2": 27.39}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 84.76, "t2": 31.25}], "q": [{"sv": "Hur bröt personen armen?", "en": "How did the person break the arm?", "o": ["Hen halkade på isen", "Hen cyklade", "Hen spelade fotboll"], "a": 0}, {"sv": "Hur länge hade hen gips?", "en": "How long did they have a cast?", "o": ["Två veckor", "Sex veckor", "Tre månader"], "a": 1}]}, {"id": "s7", "theme": 6, "kind": "Färdig berättelse", "title_sv": "Fritid: min hobby", "title_en": "Free time: my hobby", "src": "audio/s7.mp3", "src_sv": "audio/s7-sv.mp3", "dur": 81.4, "dur_sv": 30.4, "lines": [{"p": "A", "sv": "Jag ska berätta om min hobby.", "en": "I'm going to tell about my hobby.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Min hobby är promenader och simning.", "en": "My hobby is walking and swimming.", "t": 9.28, "t2": 3.86}, {"p": "A", "sv": "Jag simmar två gånger i veckan i simhallen.", "en": "I swim twice a week at the swimming hall.", "t": 20.35, "t2": 7.99}, {"p": "A", "sv": "På kvällen promenerar jag i parken.", "en": "In the evening I walk in the park.", "t": 32.22, "t2": 12.32}, {"p": "A", "sv": "Man behöver inte mycket, så det är billigt.", "en": "You don't need much, so it's cheap.", "t": 41.94, "t2": 15.81}, {"p": "A", "sv": "Det bästa är att jag mår bra och sover bättre.", "en": "The best thing is that I feel good and sleep better.", "t": 52.37, "t2": 19.71}, {"p": "A", "sv": "Därför är min hobby viktig för mig.", "en": "That's why my hobby is important to me.", "t": 65.63, "t2": 24.59}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 75.58, "t2": 28.22}], "q": [{"sv": "Hur ofta simmar personen?", "en": "How often does the person swim?", "o": ["Varje dag", "Två gånger i veckan", "En gång i månaden"], "a": 1}, {"sv": "Vad är det bästa med hobbyn?", "en": "What is the best thing about the hobby?", "o": ["Hen mår bra och sover bättre", "Den är dyr", "Hen träffar sin chef"], "a": 0}]}, {"id": "s8", "theme": 5, "kind": "Färdig berättelse", "title_sv": "Jobb: min vanliga dag", "title_en": "Work: my normal day", "src": "audio/s8.mp3", "src_sv": "audio/s8-sv.mp3", "dur": 96.9, "dur_sv": 35.9, "lines": [{"p": "A", "sv": "Jag ska berätta om min vanliga dag.", "en": "I'm going to tell about my normal day.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Jag jobbar på ett lager och studerar svenska på kvällen.", "en": "I work in a warehouse and study Swedish in the evening.", "t": 10.52, "t2": 4.34}, {"p": "A", "sv": "Jag börjar klockan sju och slutar klockan tre.", "en": "I start at seven and finish at three.", "t": 25.0, "t2": 9.66}, {"p": "A", "sv": "Först packar jag paket, sedan har jag lunch med mina kollegor.", "en": "First I pack parcels, then I have lunch with my colleagues.", "t": 37.37, "t2": 14.34}, {"p": "A", "sv": "Det bästa är mina snälla kollegor.", "en": "The best thing is my kind colleagues.", "t": 50.87, "t2": 19.12}, {"p": "A", "sv": "Det svåraste är att jobbet är tungt.", "en": "The hardest thing is that the work is heavy.", "t": 61.02, "t2": 22.76}, {"p": "A", "sv": "I mitt hemland jobbade jag på kontor, men här måste jag lära mig språket först.", "en": "In my home country I worked in an office, but here I have to learn the language first.", "t": 71.32, "t2": 26.4}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 91.13, "t2": 33.69}], "q": [{"sv": "Var jobbar personen?", "en": "Where does the person work?", "o": ["På ett lager", "På ett sjukhus", "I en skola"], "a": 0}, {"sv": "Vad gjorde hen i sitt hemland?", "en": "What did they do in their home country?", "o": ["Jobbade på kontor", "Studerade", "Jobbade på ett lager"], "a": 0}]}, {"id": "s9", "theme": 7, "kind": "Färdig berättelse", "title_sv": "Mitt liv i Finland", "title_en": "My life in Finland", "src": "audio/s9.mp3", "src_sv": "audio/s9-sv.mp3", "dur": 92.9, "dur_sv": 34.2, "lines": [{"p": "A", "sv": "Jag ska berätta om mitt liv i Finland.", "en": "I'm going to tell about my life in Finland.", "t": 0.8, "t2": 0.8}, {"p": "A", "sv": "Jag kom hit för sex år sedan, för min man fick jobb här.", "en": "I came here six years ago, because my husband got a job here.", "t": 11.37, "t2": 4.66}, {"p": "A", "sv": "I början var det svårt, för jag förstod inte språket.", "en": "At first it was hard, because I didn't understand the language.", "t": 25.42, "t2": 9.54}, {"p": "A", "sv": "Sedan började jag på en kurs och fick vänner.", "en": "Then I started a course and made friends.", "t": 38.29, "t2": 13.96}, {"p": "A", "sv": "I Finland är det tryggt och lugnt, men i mitt hemland är människorna mer öppna.", "en": "In Finland it's safe and calm, but in my home country people are more open.", "t": 48.73, "t2": 17.69}, {"p": "A", "sv": "Jag saknar min familj och vädret.", "en": "I miss my family and the weather.", "t": 68.07, "t2": 25.05}, {"p": "A", "sv": "Nu är Finland mitt hem.", "en": "Now Finland is my home.", "t": 77.84, "t2": 28.65}, {"p": "A", "sv": "Det var allt.", "en": "That's all.", "t": 87.1, "t2": 32.04}], "q": [{"sv": "Varför kom personen till Finland?", "en": "Why did the person come to Finland?", "o": ["Mannen fick jobb här", "Hen studerade", "Hen hade semester"], "a": 0}, {"sv": "Vad saknar hen?", "en": "What does she miss?", "o": ["Familjen och vädret", "Maten", "Jobbet"], "a": 0}]}];
